-- SAP ECC 6.0 -> canonical PRICE_CONDITION (SAP_A). Generated by tools/build_silver_sql.py.
SELECT 'SAP_A' AS SOURCE_SLOT, 'SAP ECC 6.0' AS SOURCE_SYSTEM, h.EBELN AS PO_NUMBER, TRY_TO_NUMBER(c.KPOSN)::STRING AS PO_ITEM, c.KSCHL AS CONDITION_TYPE,
  c.KBETR AS CONDITION_RATE, c.KWERT AS CONDITION_VALUE, c.WAERS AS CURRENCY
FROM {{ source('src_ecc_a', 'konv') }} c JOIN {{ source('src_ecc_a', 'ekko') }} h ON h.KNUMV = c.KNUMV
